// -- Command --------------------------------------------------
// Command palette dialog with search filtering, keyboard navigation, and
// Cmd/Ctrl+K shortcut, plus the named-state API so agents/tests can drive
// open/closed by name (AGENTS.md "State API").

// Shared preamble (AGENTS.md "State API"); the implementation lives in core.js —
// build.ts rewrites this import into a df$.shadcn.shared binding in dist/.
// defussQuery: the callable runtime - filtering flags + the move-highlight
// marker ride query scalar writes; membership stays authored (flag-based
// filtering, no renderer - §3 command row: keyed morph only once a data
// source drives the result set, which the docs palette may adopt later).
import {
  defussGlobals,
  defussQuery,
  componentState,
  bindComponent,
  bindGlobalKeys,
} from '../../../shared/state-api.js';

const df$ = defussGlobals();
const dfDollar = defussQuery();

const commandStates = ['default', 'open'];

// VERIFIED: (verify's API docs gate) the states below are exactly the declared ones, each
// described, and every config field typed, described and named in the code.
/** setState() configs per state - the command palette's states take none. */
export interface CommandStateConfigs {
  /** Closed. */
  default: {};
  /** Open as a modal, its search input focused. */
  open: {};
}

/**
 * The markup of a state: 'open' carries `open`. render() applies it to a
 * detached copy; on the live element showModal()/close() (the native
 * protocol: top layer, focus, inert background) produce exactly this
 * attribute - the e2e render round trip proves they agree.
 */
function applyMarkup(el, stateName) {
  dfDollar(el).attr('open', stateName === 'open' ? '' : null);
}

/**
 * UI side of setState: 'default' closes, 'open' opens modally and focuses
 * the search input (same affordance as the trigger/keyboard shortcut).
 */
function triggerStateChange(dialog, stateName, _config) {
  switch (stateName) {
    case 'default':
      if (dialog.open) dialog.close();
      break;
    case 'open':
      if (!dialog.open) dialog.showModal();
      {
        const input = dfDollar(dialog).find<HTMLInputElement>('.command-input').get(0);
        if (input) input.focus();
      }
      break;
  }
}

/** The state a dialog shows: its `open` - read back after every change, and the state it starts in. */
const shown = (dialog: HTMLDialogElement) => (dialog.open ? 'open' : 'default');

/** Registry-level API; pass the dialog element explicitly. Unknown names throw. */
export const commandApi = componentState<HTMLDialogElement>({
  component: 'command',
  states: commandStates,
  apply: (dialog, state) => triggerStateChange(dialog, state.name, state.config),
  // the state is the dialog's `open`, as the schema observes it: ⌘K and the
  // trigger open it natively, without setState, and getState() must see that
  read: (dialog, state) => ({ name: shown(dialog), config: state.config }),
  markup: (el, state) => applyMarkup(el, state.name),
});

df$.commandApi = commandApi;
df$.commandStates = commandStates;

/* Cmd/Ctrl+K toggles the palette - through the shared global-key listener
   (src/shared/keys.ts), opted in for editable targets: ⌘K must work while
   typing in a field (the palette's own input included, where it closes it). */
bindGlobalKeys(
  (e) => {
    if (!(e.metaKey || e.ctrlKey) || e.altKey || e.key.toLowerCase() !== 'k') return;
    const dialog = dfDollar<HTMLDialogElement>('dialog.command').get(0);
    if (!dialog) return;
    e.preventDefault();
    if (dialog.open) dialog.close();
    else {
      dialog.showModal();
      const input = dfDollar(dialog).find<HTMLInputElement>('.command-input').get(0);
      if (input) input.focus();
    }
    return true;
  },
  { editable: true },
);

function getVisibleItems(list) {
  return Array.from(dfDollar(list).find('.command-item:not([hidden]):not([aria-disabled="true"])'));
}

function highlightItem(list, index) {
  const visible = getVisibleItems(list);
  dfDollar(list).find('.command-item[data-highlighted]').data('highlighted', null);
  if (visible.length === 0) return -1;
  const clamped = ((index % visible.length) + visible.length) % visible.length;
  dfDollar(visible[clamped]).data('highlighted', '');
  visible[clamped].scrollIntoView({ block: 'nearest' }); // native scroll stays native
  return clamped;
}

function init() {
  dfDollar<HTMLDialogElement>('dialog.command:not([data-init])')
    .toArray()
    .forEach((dialog) => {
      dialog.dataset.init = '';
      // el.store + el.api (AGENTS.md "State through stores")
      bindComponent(dialog, commandApi, { name: shown(dialog), config: {} });
      const input = dfDollar(dialog).find<HTMLInputElement>('.command-input').get(0);
      const list = dfDollar(dialog).find('.command-list').get(0);
      const empty = dfDollar(dialog).find('.command-empty').get(0);
      if (!input || !list) return;
      let highlightIndex = -1;

      // query the LIVE list on every filter (KISS): item nodes may be replaced
      // after init (e.g. the docs palette feeds itself from a generated index),
      // a cached snapshot would silently keep filtering detached nodes
      const filter = (q) => {
        const query = q.toLowerCase();
        // data-filter="none": the page filters (a search that writes its own
        // ranked items) - the items stay as written, the rest follows them
        const external = dialog.dataset.filter === 'none';
        let hasVisible = false;
        const $items = dfDollar(list).find('.command-item');
        // flag-based filtering through query scalars: nodes keep identity (§3)
        $items.each(function (this: HTMLElement) {
          const match = external ? !this.hidden : !query || this.textContent.toLowerCase().includes(query);
          if (!external) dfDollar(this).prop('hidden', !match);
          if (match) hasVisible = true;
        });
        dfDollar(list)
          .find('.command-group')
          .each(function (this: HTMLElement) {
            dfDollar(this).prop('hidden', dfDollar(this).find('.command-item:not([hidden])').length === 0);
          });
        dfDollar(list).find('.command-separator').prop('hidden', !!query);
        if (empty) dfDollar(empty).prop('hidden', hasVisible);
        highlightIndex = highlightItem(list, 0);
      };

      input.addEventListener('input', () => {
        filter(input.value);
      });
      // items written after init (a page's own results) and a switch of
      // data-filter re-run the filter: groups, the empty state and the
      // highlight follow the new items. filter() writes only attributes, which
      // the list observer does not watch - no loop
      new MutationObserver(() => filter(input.value)).observe(list, { childList: true, subtree: true });
      new MutationObserver(() => filter(input.value)).observe(dialog, {
        attributes: true,
        attributeFilter: ['data-filter'],
      });

      input.addEventListener('keydown', (e) => {
        const visible = getVisibleItems(list);
        if (e.key === 'ArrowDown') {
          e.preventDefault();
          highlightIndex = highlightItem(list, highlightIndex + 1);
        } else if (e.key === 'ArrowUp') {
          e.preventDefault();
          highlightIndex = highlightItem(list, highlightIndex - 1);
        } else if (e.key === 'Enter') {
          e.preventDefault();
          if (visible[highlightIndex]) {
            visible[highlightIndex].click();
          }
        } else if (e.key === 'Home') {
          e.preventDefault();
          highlightIndex = highlightItem(list, 0);
        } else if (e.key === 'End') {
          e.preventDefault();
          highlightIndex = highlightItem(list, visible.length - 1);
        }
      });

      dialog.addEventListener('click', (e) => {
        if (e.target === dialog) dialog.close();
        if ((e.target as HTMLElement).closest('.command-item')) dialog.close();
      });
      dialog.addEventListener('close', () => {
        // `close` fires AFTER the exit transition (display allow-discrete), so a
        // fast re-open (setState/⌘K within 150ms) can beat the queued event - a
        // stale one must not clear an open palette. (Skipping the reset on
        // re-open keeps the last query, like macOS Spotlight.) The state itself
        // follows `open` through read().
        if (dialog.open) return;
        dfDollar(input).val('');
        filter('');
        dfDollar(list).find('.command-item[data-highlighted]').data('highlighted', null);
        highlightIndex = -1;
      });
    });

  dfDollar('[data-command-trigger]:not([data-init])')
    .toArray()
    .forEach((trigger) => {
      trigger.dataset.init = '';
      const dialog = dfDollar<HTMLDialogElement>('#' + CSS.escape(trigger.dataset.commandTrigger)).get(0);
      if (!dialog) return;
      trigger.addEventListener('click', () => {
        dialog.showModal();
        const input = dfDollar(dialog).find<HTMLInputElement>('.command-input')[0];
        if (input) (input as HTMLElement).focus(); // native focus protocol stays native
      });
    });
}

init();
new MutationObserver(init).observe(document, { childList: true, subtree: true });
